def pareto(lst):
    # lst of (cost,count): keep minimal cost for each count, dominated removed
    best = {}
    for c,n in lst:
        if n not in best or c < best[n]: best[n] = c
    out = sorted(best.items(), key=lambda t: t[1])  # by cost
    res = []; bestn = -1
    for n,c in out:
        if n > bestn: res.append((c,n)); bestn = n
    return res

def combine(A, B):
    return pareto([(c1+c2, n1+n2) for c1,n1 in A for c2,n2 in B])

